"use strict";(globalThis.webpackChunkvalm23_github_io||=[]).push([[715],{3966(e,t,a){a.r(t),a.d(t,{default:()=>h,metadata:()=>n});var n=a(8094),o=a(4848),r=a(8453);const i={authorsImageUrls:[void 0]};function s(e){const t={h2:"h2",hr:"hr",p:"p",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"I left my last full-time job in September 2025, eight years in. If you found this through my resume, you're probably wondering about the gap. I'd rather you read it here than guess."}),"\n",(0,o.jsx)(t.h2,{id:"who-is-matthew-valdez",children:"Who is Matthew Valdez?"}),"\n",(0,o.jsx)(t.p,{children:"For eight years I was the human in the loop at a network operations center, working a ticket queue for twelve hours a day. Network changes, service outages, ISPs and vendors on both sides of the phone, repair windows that were never long enough. We kept the network up while leadership openly ranked us below the \"real\" engineers down the hall. We made it work anyway. That's the honest version of what I did: I took everyone's problem and made it my problem until it was fixed."}),"\n",(0,o.jsx)(t.h2,{id:"what-has-their-career-been-like",children:"What has their career been like?"}),"\n",(0,o.jsx)(t.p,{children:"I got good at it, and I stayed level one. I trained my juniors and watched them get promoted to the tier above me while I sat in the same seat. Eventually the overtime stopped, and I got reassigned under someone management knew I didn't work well with, framed as mentorship. I already knew what I was worth, I'd been told in my 1:1s that I was more effective than the person I was assigned to learn from."}),"\n",(0,o.jsx)(t.p,{children:"I spent seven years at that one place, knowing it was never going to let me grow. I just didn't know how to leave until staying was worse than the alternative."}),"\n",(0,o.jsx)(t.h2,{id:"what-are-they-building-outside-an-office",children:"What are they building outside an office?"}),"\n",(0,o.jsx)(t.p,{children:"The last year was the most productive of my career, and none of it happened at a desk I was assigned to."}),"\n",(0,o.jsx)(t.p,{children:"I set up a Tailscale network so I could do remote security research with my penetration testing collaborator on software we actually built. I rebuilt this site. I built my own infrastructure from scratch, self-hosted Linux, CI/CD, hardened as I went."}),"\n",(0,o.jsx)(t.p,{children:"The AI stuff is what I'm proudest of. A year ago I was using AI to make music and screw around. Now I run my own models with Ollama, build agent harnesses, write system prompts, and configure them to actually do the job, including the permissive setups the sanitized consumer tools won't give you. That's a skill most security engineers still don't have."}),"\n",(0,o.jsx)(t.p,{children:"The hardest thing I figured out this year was a CTF challenge where I had to craft a packet that slipped past a firewall's header filters to reach the box behind it. That's when lateral thinking stopped being a buzzword and became how I actually attack a problem."}),"\n",(0,o.jsx)(t.h2,{id:"are-they-worth-hiring",children:"Are they worth hiring?"}),"\n",(0,o.jsx)(t.p,{children:"You want a unicorn, because your hiring manager wants one. I can be that faster and cheaper than the guy with a degree and an ego, and I'm the kind that admits when I'm wrong and actually fixes it. I'm an operator, I work hard, and I've survived worse than anything you'd hand me."}),"\n",(0,o.jsx)(t.p,{children:"And I won't be a pawn. I don't nod along when something contradicts what the company says it stands for, and I don't paper over management's failures. I think like an owner because I am one. I run my own business. You'd get that same owner's mindset."}),"\n",(0,o.jsx)(t.hr,{}),"\n",(0,o.jsx)(t.p,{children:"The part the resume doesn't say."}),"\n",(0,o.jsx)(t.p,{children:"I'm a trans woman. My name is Roxanna, Roxy to the people who know me. The gap exists because I came out, and the place I gave eight years to didn't have room for me once I did."}),"\n",(0,o.jsx)(t.p,{children:"Finding a harbor meant finally doing the things I'd been too scared to touch. Building the malware and then defanging it, so I understand the attack side from the inside instead of just reading about it. Committing to my own thing and building it until it drew real eyes. That's what the last year actually was."}),"\n",(0,o.jsx)(t.p,{children:"The most serious of that work you won't find on my public portfolio. Not because it isn't real, but because it's too severe to sit on the open internet. Ask me in an interview, and I'll show you."}),"\n",(0,o.jsx)(t.p,{children:"I'm done shrinking to fit. If you hire me, you get all of it. You get Roxy."})]})}function h(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(s,{...e})}):s(e)}a.d(t,["assets",0,i,"contentTitle",0,void 0,"frontMatter",0,{title:"Matthew Valdez",authors:["roxy"],tags:["career"]},"toc",0,[{value:"Who is Matthew Valdez?",id:"who-is-matthew-valdez",level:2},{value:"What has their career been like?",id:"what-has-their-career-been-like",level:2},{value:"What are they building outside an office?",id:"what-are-they-building-outside-an-office",level:2},{value:"Are they worth hiring?",id:"are-they-worth-hiring",level:2}]])},8453(e,t,a){a.d(t,{R:()=>i,x:()=>s});var n=a(6540);const o={},r=n.createContext(o);function i(e){const t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),n.createElement(r.Provider,{value:t},e.children)}},8094(e){e.exports=JSON.parse('{"permalink":"/writeups/2026/08/22/the-gap","source":"@site/blog/2026-08-22-the-gap/index.md","title":"Matthew Valdez","description":"I left my last full-time job in September 2025, eight years in. If you found this through my resume, you\'re probably wondering about the gap. I\'d rather you read it here than guess.","date":"2026-08-22T00:00:00.000Z","tags":[{"inline":true,"label":"career","permalink":"/writeups/tags/career"}],"readingTime":3.43,"hasTruncateMarker":true,"authors":[{"name":"Roxy","title":"Offensive Security Researcher","url":"https://github.com/valm23","key":"roxy","page":null}],"frontMatter":{"title":"Matthew Valdez","authors":["roxy"],"tags":["career"]},"unlisted":false,"nextItem":{"title":"Killing a rate-limit bug by moving an API call from the browser to the build","permalink":"/writeups/2026/08/01/build-time-fetching"}}')}}]);